#include <iostream>
#include <stack>
#include <vector>
using namespace std;

int main() {
    vector<int> a = {2, 1, 4, 3};
    stack<int> st;
    for (int x : a) {
        while (!st.empty() && st.top() <= x) st.pop();
        st.push(x);
    }
    cout << st.size() << '\n';
    return 0;
}

